pub fn clamp(x: i64, lo: i64, hi: i64) -> i64 {
    if x < lo {
        lo
    } else if x > hi {
        hi
    } else {
        x
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    proptest! {
        #[test]
        fn prop(x in any::<i64>(), a in any::<i64>(), b in any::<i64>()) {
            let (lo, hi) = if a <= b { (a, b) } else { (b, a) };
            let r = clamp(x, lo, hi);
            prop_assert!(r >= lo && r <= hi);
            if x >= lo && x <= hi { prop_assert_eq!(r, x); }
        }
    }

    #[test]
    fn basic() {
        assert_eq!(clamp(5, 0, 3), 3);
        assert_eq!(clamp(-5, 0, 3), 0);
        assert_eq!(clamp(2, 0, 3), 2);
        assert_eq!(clamp(i64::MIN, i64::MIN, i64::MAX), i64::MIN);
    }
}

pub fn midpoint(a: i64, b: i64) -> i64 {
    (a & b) + ((a ^ b) >> 1)
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    fn reference(a: i64, b: i64) -> i64 {
        (a as i128 + b as i128).div_euclid(2) as i64
    }

    #[test]
    fn edges() {
        let v = [i64::MIN, i64::MIN + 1, -3, -2, -1, 0, 1, 2, 3, i64::MAX - 1, i64::MAX];
        for &a in &v {
            for &b in &v {
                assert_eq!(midpoint(a, b), reference(a, b), "{a} {b}");
            }
        }
    }

    proptest! {
        #[test]
        fn matches(a in any::<i64>(), b in any::<i64>()) {
            prop_assert_eq!(midpoint(a, b), reference(a, b));
        }
    }
}

pub fn sat_sum(a: &[i64]) -> i64 {
    a.iter().fold(0i64, |acc, &x| acc.saturating_add(x))
}

#[cfg(test)]
