        assert_eq!(sat_sum(&[]), 0);
        assert_eq!(sat_sum(&[i64::MAX, 1, -5]), i64::MAX - 5);
        assert_eq!(sat_sum(&[i64::MIN, -1, 5]), i64::MIN + 5);
    }
}

pub fn count_in_range(a: &[i64], lo: i64, hi: i64) -> usize {
    if lo > hi {
        return 0;
    }
    a.iter().filter(|&&x| lo <= x && x <= hi).count()
}

#[cfg(test)]
