        assert_eq!(count_in_range(&[1, 2, 3, i64::MIN, i64::MAX], 2, i64::MAX), 3);
        assert_eq!(count_in_range(&[1, 2, 3], 3, 2), 0);
        assert_eq!(count_in_range(&[], 0, 0), 0);
    }
}

pub fn first_max_index(a: &[i64]) -> usize {
    let mut best = 0;
    for i in 1..a.len() {
        if a[i] > a[best] {
            best = i;
        }
    }
    best
}

