        assert_eq!(first_max_index(&[i64::MIN]), 0);
        assert_eq!(first_max_index(&[5, 5, 5]), 0);
        assert_eq!(first_max_index(&[i64::MIN, i64::MAX, i64::MAX]), 1);
    }
}

pub fn last_min_index(a: &[i64]) -> usize {
    let mut best = 0;
    for (i, &v) in a.iter().enumerate() {
        if v <= a[best] {
            best = i;
        }
    }
    best
}

