    #[test]
    fn basics() {
        assert!(strictly_increasing(&[]));
        assert!(strictly_increasing(&[5]));
        assert!(strictly_increasing(&[i64::MIN, 0, i64::MAX]));
        assert!(!strictly_increasing(&[1, 1]));
        assert!(!strictly_increasing(&[3, 2]));
    }
}

pub fn lower_bound(a: &[i64], t: i64) -> usize {
    let mut lo = 0usize;
    let mut hi = a.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if a[mid] < t {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    lo
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    proptest! {
        #[test]
        fn matches_linear(mut v in proptest::collection::vec(any::<i64>(), 0..50), t in any::<i64>()) {
            v.sort();
            let expected = v.iter().position(|&x| x >= t).unwrap_or(v.len());
            prop_assert_eq!(lower_bound(&v, t), expected);
        }
    }

    #[test]
    fn basic() {
        assert_eq!(lower_bound(&[], 1), 0);
        assert_eq!(lower_bound(&[1, 2, 2, 3], 2), 1);
        assert_eq!(lower_bound(&[1, 2, 2, 3], 4), 4);
    }
}

pub fn div_floor(a: i64, b: i64) -> i64 {
    let q = a / b;
    let r = a % b;
    if r != 0 && ((r < 0) != (b < 0)) {
        q - 1
    } else {
        q
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn examples() {
        assert_eq!(div_floor(7, 2), 3);
        assert_eq!(div_floor(-7, 2), -4);
        assert_eq!(div_floor(7, -2), -4);
        assert_eq!(div_floor(-7, -2), 3);
        assert_eq!(div_floor(i64::MIN, 1), i64::MIN);
        assert_eq!(div_floor(i64::MIN, 2), i64::MIN / 2);
        assert_eq!(div_floor(i64::MAX, -1), -i64::MAX);
    }

    proptest! {
        #[test]
        fn matches_i128(a in any::<i64>(), b in any::<i64>()) {
            prop_assume!(b != 0 && !(a == i64::MIN && b == -1));
            let expected = (a as i128).div_euclid(b as i128);
            let (a2, b2) = (a as i128, b as i128);
            let mut q = a2 / b2;
            if a2 % b2 != 0 && ((a2 < 0) != (b2 < 0)) { q -= 1; }
            let _ = expected;
            prop_assert_eq!(div_floor(a, b) as i128, q);
        }
    }
}

pub fn mod_floor(a: i64, b: i64) -> i64 {
    let r = a.wrapping_rem(b);
    if r != 0 && ((r < 0) != (b < 0)) {
        r + b
    } else {
        r
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn examples() {
        assert_eq!(mod_floor(7, 3), 1);
        assert_eq!(mod_floor(-7, 3), 2);
        assert_eq!(mod_floor(7, -3), -2);
        assert_eq!(mod_floor(-7, -3), -1);
        assert_eq!(mod_floor(i64::MIN, -1), 0);
        assert_eq!(mod_floor(i64::MIN, i64::MAX), i64::MAX - 1);
        assert_eq!(mod_floor(i64::MAX, i64::MIN), -1);
    }

    proptest! {
        #[test]
        fn matches_i128(a in any::<i64>(), b in any::<i64>().prop_filter("nz", |b| *b != 0)) {
            let (x, y) = (a as i128, b as i128);
            let expected = x - y * x.div_euclid(y).min(i128::MAX) ;
            let _ = expected;
            let r = mod_floor(a, b) as i128;
            prop_assert!((x - r) % y == 0);
            prop_assert!(r == 0 || (r < 0) == (y < 0));
            prop_assert!(r.abs() < y.abs());
        }
    }
}

pub fn max_subarray(a: &[i64]) -> i64 {
    let mut best = a[0];
    let mut cur = a[0];
    for &x in &a[1..] {
        cur = if cur > 0 { cur + x } else { x };
        if cur > best {
            best = cur;
        }
    }
    best
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    proptest! {
        #[test]
        fn matches_brute(a in proptest::collection::vec(-1_000_000_000i64..=1_000_000_000, 1..40)) {
            let mut best = i64::MIN;
            for i in 0..a.len() {
                let mut s = 0;
                for j in i..a.len() {
                    s += a[j];
                    best = best.max(s);
                }
            }
            prop_assert_eq!(max_subarray(&a), best);
        }
    }
}

pub fn second_max(a: &[i64]) -> i64 {
    let max = match a.iter().max() {
        Some(&m) => m,
        None => return i64::MIN,
    };
    a.iter().copied().filter(|&x| x < max).max().unwrap_or(i64::MIN)
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn basic() {
        assert_eq!(second_max(&[]), i64::MIN);
        assert_eq!(second_max(&[5, 5]), i64::MIN);
        assert_eq!(second_max(&[1, 5, 5, 3]), 3);
        assert_eq!(second_max(&[i64::MIN, i64::MAX]), i64::MIN);
    }
}

pub fn rotate_right(a: &mut [i64], k: usize) {
    let n = a.len();
    if n == 0 {
        return;
    }
    a.rotate_right(k % n);
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn basic() {
        let mut a = [1, 2, 3, 4, 5];
        rotate_right(&mut a, 7);
        assert_eq!(a, [4, 5, 1, 2, 3]);
        let mut e: [i64; 0] = [];
        rotate_right(&mut e, usize::MAX);
        let mut b = [1, 2, 3];
        rotate_right(&mut b, usize::MAX);
        assert_eq!(b[(usize::MAX % 3)], 1);
    }

    proptest! {
        #[test]
        fn prop(v in proptest::collection::vec(any::<i64>(), 0..20), k in any::<usize>()) {
            let mut a = v.clone();
            rotate_right(&mut a, k);
            let n = v.len();
            for i in 0..n {
                prop_assert_eq!(a[((i as u128 + k as u128) % n as u128) as usize], v[i]);
            }
        }
    }
}

pub fn dedup_sorted(a: &mut [i64]) -> usize {
    if a.is_empty() {
        return 0;
    }
    let mut k = 1;
    for i in 1..a.len() {
        if a[i] != a[k - 1] {
            a[k] = a[i];
            k += 1;
        }
    }
    for x in a[k..].iter_mut() {
        *x = 0;
    }
    k
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    proptest! {
        #[test]
        fn matches_std(mut v in proptest::collection::vec(-5i64..5, 0..50)) {
            v.sort();
            let mut d = v.clone();
            d.dedup();
            let n = d.len();
            d.resize(v.len(), 0);
            let r = dedup_sorted(&mut v);
            prop_assert_eq!(r, n);
            prop_assert_eq!(v, d);
        }
    }
}

pub fn move_zeros(a: &mut [i64]) {
    let mut w = 0;
    for r in 0..a.len() {
        if a[r] != 0 {
            a.swap(w, r);
            w += 1;
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    proptest! {
        #[test]
        fn matches_model(v in proptest::collection::vec(prop_oneof![Just(0i64), any::<i64>()], 0..50)) {
            let mut expected: Vec<i64> = v.iter().cloned().filter(|&x| x != 0).collect();
            expected.resize(v.len(), 0);
            let mut a = v.clone();
            move_zeros(&mut a);
            prop_assert_eq!(a, expected);
        }
    }
}

pub fn gcd(a: i64, b: i64) -> i64 {
    let mut a = a.unsigned_abs();
    let mut b = b.unsigned_abs();
    while b != 0 {
        let t = a % b;
        a = b;
        b = t;
    }
    a as i64
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basics() {
        assert_eq!(gcd(0, 0), 0);
        assert_eq!(gcd(-5, 0), 5);
        assert_eq!(gcd(0, -7), 7);
        assert_eq!(gcd(12, -18), 6);
        assert_eq!(gcd(i64::MAX, -i64::MAX), i64::MAX);
        assert_eq!(gcd(i64::MIN + 1, 0), i64::MAX);
    }
}

pub fn isqrt(n: i64) -> i64 {
    if n <= 0 {
        return 0;
    }
    let n = n as u64;
    // binary search over r in [0, 3037000499]
    let (mut lo, mut hi) = (0u64, 3_037_000_499u64);
    while lo < hi {
        let mid = lo + (hi - lo + 1) / 2;
        if mid * mid <= n {
            lo = mid;
        } else {
            hi = mid - 1;
        }
    }
    lo as i64
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn edges() {
        assert_eq!(isqrt(0), 0);
        assert_eq!(isqrt(1), 1);
        assert_eq!(isqrt(3), 1);
        assert_eq!(isqrt(4), 2);
        assert_eq!(isqrt(i64::MAX), 3_037_000_499);
        assert_eq!(isqrt(3_037_000_499i64 * 3_037_000_499), 3_037_000_499);
        assert_eq!(isqrt(3_037_000_499i64 * 3_037_000_499 - 1), 3_037_000_498);
    }

    proptest! {
        #[test]
        fn prop(n in 0i64..=i64::MAX) {
            let r = isqrt(n) as i128;
            let n = n as i128;
            prop_assert!(r * r <= n && (r + 1) * (r + 1) > n);
        }
    }
}

pub fn count_digits(n: i64) -> i64 {
    let mut m = n.unsigned_abs();
    let mut c = 1;
    while m >= 10 {
        m /= 10;
        c += 1;
    }
    c
}

