        assert_eq!(count_digits(0), 1);
        assert_eq!(count_digits(-5), 1);
        assert_eq!(count_digits(10), 2);
        assert_eq!(count_digits(-999), 3);
        assert_eq!(count_digits(i64::MAX), 19);
        assert_eq!(count_digits(i64::MIN), 19);
    }
}

