pub fn majority(a: &[i64]) -> i64 {
    let mut cand = 0i64;
    let mut cnt = 0usize;
    for &x in a {
        if cnt == 0 {
            cand = x;
            cnt = 1;
        } else if x == cand {
            cnt += 1;
        } else {
            cnt -= 1;
        }
    }
    let c = a.iter().filter(|&&x| x == cand).count();
    if c > a.len() / 2 && !a.is_empty() {
        cand
    } else {
        i64::MIN
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn basic() {
        assert_eq!(majority(&[]), i64::MIN);
        assert_eq!(majority(&[1, 2, 1]), 1);
        assert_eq!(majority(&[1, 2, 1, 2]), i64::MIN);
        assert_eq!(majority(&[2, 2, 1, 1, 2]), 2);
        assert_eq!(majority(&[0]), 0);
    }
}

pub fn longest_run(a: &[i64]) -> usize {
    let mut best = 0usize;
    let mut cur = 0usize;
    for i in 0..a.len() {
        if i > 0 && a[i] == a[i - 1] {
            cur += 1;
        } else {
            cur = 1;
        }
        if cur > best {
            best = cur;
        }
    }
    best
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn basic() {
        assert_eq!(longest_run(&[]), 0);
        assert_eq!(longest_run(&[1, 2, 3]), 1);
        assert_eq!(longest_run(&[1, 1, 2, 2, 2, 1]), 3);
        assert_eq!(longest_run(&[5, 5]), 2);
    }
}

pub fn merge_sorted(a: &[i64], b: &[i64], out: &mut [i64]) {
    let (mut i, mut j) = (0, 0);
    for slot in out.iter_mut() {
        if j >= b.len() || (i < a.len() && a[i] <= b[j]) {
            *slot = a[i];
            i += 1;
        } else {
            *slot = b[j];
            j += 1;
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    proptest! {
        #[test]
        fn merges(mut a in proptest::collection::vec(any::<i64>(), 0..30),
                  mut b in proptest::collection::vec(any::<i64>(), 0..30)) {
            a.sort(); b.sort();
            let mut out = vec![7; a.len() + b.len()];
            merge_sorted(&a, &b, &mut out);
            let mut e = a.clone(); e.extend(&b); e.sort();
            prop_assert_eq!(out, e);
        }
    }
}

