pub fn pow_mod(base: i64, exp: i64, m: i64) -> i64 {
    let m = m as u128;
    let mut b = (base as u128) % m;
    let mut e = exp as u64;
    let mut r: u128 = 1 % m;
    while e > 0 {
        if e & 1 == 1 {
            r = r * b % m;
        }
        b = b * b % m;
        e >>= 1;
    }
    r as i64
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basics() {
        assert_eq!(pow_mod(0, 0, 1), 0);
        assert_eq!(pow_mod(0, 0, 7), 1);
        assert_eq!(pow_mod(2, 10, 1000), 24);
        assert_eq!(pow_mod(3, 0, 5), 1);
        assert_eq!(pow_mod(i64::MAX, i64::MAX, 3_000_000_000), pow_mod(i64::MAX % 3_000_000_000, i64::MAX, 3_000_000_000));
    }
}
